const B64_LOOKUP = new Uint8Array(128);
(function initB64() {
  const alpha = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  for (let i = 0; i < alpha.length; i++) B64_LOOKUP[alpha.charCodeAt(i)] = i;
})();

export function decodeBase64(b64: string): Uint8Array {
  const len = b64.length;
  let pad = 0;
  if (len >= 2 && b64.charCodeAt(len - 1) === 61) pad++;
  if (len >= 2 && b64.charCodeAt(len - 2) === 61) pad++;
  const outLen = ((len * 3) >>> 2) - pad;
  const out = new Uint8Array(outLen);
  let p = 0;
  for (let i = 0; i < len; i += 4) {
    const a = B64_LOOKUP[b64.charCodeAt(i)]!;
    const b = B64_LOOKUP[b64.charCodeAt(i + 1)]!;
    const c = B64_LOOKUP[b64.charCodeAt(i + 2)]!;
    const d = B64_LOOKUP[b64.charCodeAt(i + 3)]!;
    out[p++] = (a << 2) | (b >> 4);
    if (p < outLen) out[p++] = ((b & 15) << 4) | (c >> 2);
    if (p < outLen) out[p++] = ((c & 3) << 6) | d;
  }
  return out;
}

function f16ToF32(h: number): number {
  const s = (h & 0x8000) ? -1 : 1;
  const e = (h >> 10) & 0x1f;
  const m = h & 0x03ff;
  if (e === 0) return s * Math.pow(2, -14) * (m / 1024);
  if (e === 31) return m ? NaN : s * Infinity;
  return s * Math.pow(2, e - 15) * (1 + m / 1024);
}

export interface NnueWeights {
  readonly w1s: Float32Array;
  readonly w1d: Float32Array;
  readonly b1: Float32Array;
  readonly w2: Float32Array;
  readonly b2: Float32Array;
  readonly w3: Float32Array;
  readonly b3: Float32Array;
}

let cachedWeights: NnueWeights | null = null;
let cachedAllFloats: Float32Array | null = null;
let cachedBinary: Uint8Array | null = null;

export function getNnueWeights(): NnueWeights {
  if (cachedWeights) return cachedWeights;
  const bytes = decodeBase64(WEIGHTS_F16_B64);
  const count = bytes.length >>> 1;
  const all = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    all[i] = f16ToF32(bytes[i * 2]! | (bytes[i * 2 + 1]! << 8));
  }
  cachedAllFloats = all;
  let off = 0;
  const take = (n: number) => { const s = all.subarray(off, off + n); off += n; return s; };
  const w1s = take(NNUE_IN_SPARSE * NNUE_H1);
  const w1d = take(NNUE_IN_DENSE * NNUE_H1);
  const b1 = take(NNUE_H1);
  const w2 = take(NNUE_NUM_BUCKETS * NNUE_H1 * NNUE_H2);
  const b2 = take(NNUE_NUM_BUCKETS * NNUE_H2);
  const w3 = take(NNUE_NUM_BUCKETS * NNUE_H2);
  const b3 = take(NNUE_NUM_BUCKETS);
  const built: NnueWeights = { w1s, w1d, b1, w2, b2, w3, b3 };
  cachedWeights = built;
  return built;
}

export function getNnueBinary(): Uint8Array {
  if (cachedBinary) return cachedBinary;
  getNnueWeights();
  const all = cachedAllFloats!;
  const out = new Uint8Array(40 + all.byteLength);
  const dv = new DataView(out.buffer);
  dv.setUint32(0, 0x514e5545, true);
  dv.setInt32(4, NNUE_VERSION, true);
  dv.setInt32(8, NNUE_IN_SPARSE, true);
  dv.setInt32(12, NNUE_IN_DENSE, true);
  dv.setInt32(16, NNUE_H1, true);
  dv.setInt32(20, NNUE_H2, true);
  dv.setInt32(24, NNUE_NUM_BUCKETS, true);
  dv.setFloat32(28, NNUE_BLEND_ALPHA, true);
  dv.setFloat32(32, NNUE_SCORE_SCALE, true);
  dv.setFloat32(36, NNUE_CLAIM_BLEND_ALPHA, true);
  out.set(new Uint8Array(all.buffer, all.byteOffset, all.byteLength), 40);
  cachedBinary = out;
  return out;
}
